insert into indicators (name, description, measurement_unit_id, direction) select 'Cumprir prazo de atendimento de chamados.', 'Atendimento de chamados dentro do prazo de 3 dias uteis, a contar da data de recebimento no fluxo administrativo', mu.id, 'menor_melhor' from measurement_units mu where mu.code='DIAS' and not exists (select 1 from indicators i2 where i2.name='Cumprir prazo de atendimento de chamados.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Cumprir prazo de faturamento (lançamento) notas fiscais', 'Lançar as notas fiscais em até 3 dias úteis, à contar da data de seu recebimento pelo setor administrativo', mu.id, 'menor_melhor' from measurement_units mu where mu.code='DIAS' and not exists (select 1 from indicators i2 where i2.name='Cumprir prazo de faturamento (lançamento) notas fiscais');
insert into indicators (name, description, measurement_unit_id, direction) select 'Governança da Área Administrativa', 'Estruturar o modelo de governança da Área Administrativa até dezembro de 2026, contemplando a implantação de indicadores gerenciais, padronização dos processos críticos, implantação da gestão de riscos, rotina de acompanhamento dos resultados e gestão dos planos de ação para melhoria contínua.', mu.id, 'cronologico' from measurement_units mu where mu.code='MES' and not exists (select 1 from indicators i2 where i2.name='Governança da Área Administrativa');
insert into indicators (name, description, measurement_unit_id, direction) select 'Mapear, Classificar, Padronizar e Escrever 80% dos processos Críticos Administrativos', 'Mapear 100% dos processos e atividades da Área Administrativa, definir a criticidade e a priorização dos processos por meio de critérios estabelecidos e documentar, escrever, validar e publicar 80% dos procedimentos dos processos classificados como críticos até dezembro de 2026.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Mapear, Classificar, Padronizar e Escrever 80% dos processos Críticos Administrativos');
insert into indicators (name, description, measurement_unit_id, direction) select 'Treinamento de Compliance', 'Realização de 100% dos treinamentos de Compliance durante o ano', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Treinamento de Compliance');
insert into indicators (name, description, measurement_unit_id, direction) select 'Gestão de fundo fixo das PCH', 'Assegurar 100% de disponibilidade e conformidade do fundo fixo das PCHs, realizando o registro diário de todas as entradas, saídas e baixas de comprovantes, e solicitando a reposição do saldo sempre que este atingir o limite mínimo de 30%, zerando a ocorrência de falta de saldo para despesas imediatas.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Gestão de fundo fixo das PCH');
insert into indicators (name, description, measurement_unit_id, direction) select 'Gestão dos pedidos de abastecimento (TicketLog) de todas as usinas do grupo Âmbar.', 'Garantir 100% de saldo disponível para o lançamento das notas fiscais do fornecedor Ticket Log em todas as usinas do Grupo Âmbar ao longo de todo o ano, realizando o planejamento e a liberação dos pedidos de abastecimento de forma antecipada, visando eliminar completamente (zero ocorrências) interrupções operacionais ou fiscais por insuficiência de saldo.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Gestão dos pedidos de abastecimento (TicketLog) de todas as usinas do grupo Âmbar.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implantação do Paytrack Expense (Adiantamento, Acerto de viagens, etc)', 'Implantação do Paytrack Expense (Adiantamento, Acerto de viagens, etc)', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Implantação do Paytrack Expense (Adiantamento, Acerto de viagens, etc)');
insert into indicators (name, description, measurement_unit_id, direction) select 'Atualizar, validar e publicar a Política de Viagens da companhia.', 'Rever, validar e publicar a nova Política de Viagens da empresa até Dez/26, incluindo a atualização e o alinhamento dos valores de reembolso e despesas praticados face ao mercado atual', mu.id, 'cronologico' from measurement_units mu where mu.code='MES' and not exists (select 1 from indicators i2 where i2.name='Atualizar, validar e publicar a Política de Viagens da companhia.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Promover a melhoria contínua dos processos administrativos.', 'Implementar, no mínimo, 2 iniciativas de melhoria contínua nos processos da área até dezembro de 2026, assegurando que cada iniciativa apresente evidências objetivas dos ganhos obtidos em produtividade, padronização, redução de retrabalho, redução de custos ou eficiência operacional.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='QTDE' and not exists (select 1 from indicators i2 where i2.name='Promover a melhoria contínua dos processos administrativos.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Mapear, Classificar, Padronizar e Escrever 100% dos processos Críticos Administrativos', 'Mapear 100% dos processos e atividades da Área Administrativa, definir a criticidade e a priorização dos processos por meio de critérios estabelecidos e documentar, escrever, validar e publicar 100% dos procedimentos dos processos classificados como críticos até dezembro de 2026.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Mapear, Classificar, Padronizar e Escrever 100% dos processos Críticos Administrativos');
insert into indicators (name, description, measurement_unit_id, direction) select 'Assegurar que remessas retornem dentro do prazo', 'Garantir que as remessas para conserto retornem dentro do prazo previsto na legislação da SEFAZ/AM ou, quando aplicável, que as prorrogações e regularizações fiscais sejam realizadas antes do vencimento do prazo legal, evitando ocorrências de não conformidade, exceto casos de força maior devidamente registrados e aprovados, situações em que o atraso decorra exclusivamente de ato da autoridade fiscal, desde que documentado.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Assegurar que remessas retornem dentro do prazo');
insert into indicators (name, description, measurement_unit_id, direction) select 'Reduzir cadastros em duplicidade de produtos', 'Realizar o levantamento de todos os produtos habilitados para a Âmbar, identificar os cadastros duplicados e reduzir em 30% o volume de duplicidades identificado no diagnóstico inicial até dezembro de 2026, promovendo a padronização e a qualidade do cadastro de produtos.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Reduzir cadastros em duplicidade de produtos');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implantar o processo de gestão documental de terceiros dos contratos administrativos.', 'Implantar o processo de gestão documental de terceiros dos contratos administrativos até dezembro de 2026, garantindo a validação da documentação obrigatória previamente à liberação dos pagamentos. Nos casos de documentação pendente, assegurar o bloqueio preventivo do pagamento até a regularização documental, mitigando riscos trabalhistas, fiscais e contratuais para a empresa.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Implantar o processo de gestão documental de terceiros dos contratos administrativos.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implantar 5 projetos de automatização de processos até dezembro de 2026', 'Garantir a entrega e a entrada em produção de 5 projetos sistêmicos estruturantes (Portal do Parceiro, Paytrack, Portal do Fornecedor, Portal Aceite de Serviço e BI Administrativo de NFs não escrituradas) até Dez/26, com validação das áreas de negócio, visando a automação de processos, melhoria no relacionamento com parceiros/fornecedores e aumento do controle fiscal administrativo.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='QTDE' and not exists (select 1 from indicators i2 where i2.name='Implantar 5 projetos de automatização de processos até dezembro de 2026');
insert into indicators (name, description, measurement_unit_id, direction) select 'Garantir entrega das Metas das áreas que estão sob sua Gestão', 'Elevar entrega da equipe através de acompanhamento contínuo, garantindo que cada área sob sua gestão atinja um nível mínimo de 90% de cumprimento em sua respectiva carta de metas', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Garantir entrega das Metas das áreas que estão sob sua Gestão');
insert into indicators (name, description, measurement_unit_id, direction) select 'Efetuar a padronização dos Itens de Facilities', 'Padronizar os itens de Copa, Cozinha, Limpeza e Higiene em todas as usinas da Regional Norte até Setembro de 2026', mu.id, 'cronologico' from measurement_units mu where mu.code='MES' and not exists (select 1 from indicators i2 where i2.name='Efetuar a padronização dos Itens de Facilities');
insert into indicators (name, description, measurement_unit_id, direction) select 'Centralização da Compra de itens de Facilities com redução de Custo', 'Centralização das compras por meio da Área Administrativa e alcançando redução mínima de 10% no custo total, comparando o acumulado do segundo semestre com o primeiro semestre de 2026.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Centralização da Compra de itens de Facilities com redução de Custo');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implantar sistema de gestão da qualidade dos serviços de Limpeza e Jardinagem.', 'Implantar o sistema de gestão da qualidade dos serviços de Limpeza e Jardinagem até dezembro de 2026, por meio da implementação de check-lists de inspeção e pesquisa de satisfação dos clientes internos, garantindo a avaliação contínua dos serviços, o tratamento das não conformidades e índice mínimo de satisfação de 90%.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Implantar sistema de gestão da qualidade dos serviços de Limpeza e Jardinagem.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Garantir que o percentual-meta de notas fiscais elegíveis seja registrado dentro do respectivo mês de apuração, promovendo eficiência e conformidade fiscal', 'Garantir o lançamento das notas aptas recebidas no administrativo, assegurando que no mínimo, 90% das notas enviadas para lançamento sejam concluídas dentro do prazo de fechamento mensal, com apuração mensal baseado na relação entre o total de notas recebidas e o total de notas pendentes de lançamento ao final do período.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Garantir que o percentual-meta de notas fiscais elegíveis seja registrado dentro do respectivo mês de apuração, promovendo eficiência e conformidade fiscal');
insert into indicators (name, description, measurement_unit_id, direction) select 'Mapeamento dos itens sem Movimentação', 'Mapear itens sem consumo, excluindo críticos, obsoletos, aplicação imediata, patrimônio, itens consumidos, comprados e zerados, conforme relatório da usina', mu.id, 'maior_melhor' from measurement_units mu where mu.code='QTDE' and not exists (select 1 from indicators i2 where i2.name='Mapeamento dos itens sem Movimentação');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implantar 6 projetos de automatização de processos até dezembro de 2026', 'Proporcionando redução mínima de 20% no tempo de execução dos processos automatizados e garantindo a adoção efetiva pelas áreas usuárias ((Gestão Paytrack, Portal do Parceiro, Portal do Fornecedor, BI ADM, Portal aceite de Serviços, BI do Almoxarifado)', mu.id, 'maior_melhor' from measurement_units mu where mu.code='QTDE' and not exists (select 1 from indicators i2 where i2.name='Implantar 6 projetos de automatização de processos até dezembro de 2026');
insert into indicators (name, description, measurement_unit_id, direction) select 'Garantir entrega das Metas das áreas que estão sob sua Gestão.', 'Elevar entrega da equipe através de acompanhamento contínuo, garantindo que cada área sob sua gestão atinja um nível mínimo de 90% de cumprimento em sua respectiva carta de metas', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Garantir entrega das Metas das áreas que estão sob sua Gestão.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Acuracidade de estoque – Inventário geral sob gestão', 'Assegurar a acuracidade do estoque através do inventário geral desde o início das operações', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Acuracidade de estoque – Inventário geral sob gestão');
insert into indicators (name, description, measurement_unit_id, direction) select 'Saneamento e Unificação do Cadastro de Itens', 'Indicador: Percentual de itens duplicados identificados, saneados (unificados/inativados) e corrigidos no sistema. Mapear 100% da base e sanar os itens duplicados identificados conforme tabela até junho 2026', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Saneamento e Unificação do Cadastro de Itens');
insert into indicators (name, description, measurement_unit_id, direction) select 'Criação e implementação de POPs (Book ABNT)', 'Criar e implementar POPs padronizados e específicos organizados em Book conforme ABNT, garantindo padronização e rastreabilidade', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Criação e implementação de POPs (Book ABNT)');
insert into indicators (name, description, measurement_unit_id, direction) select 'Otimização financeira dos contratos', 'Implementar ações que gerem redução mínima de 5% no custo anual dos contratos elegíveis sob gestão, preservando os níveis de serviço (SLA) e compliance.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Otimização financeira dos contratos');
insert into indicators (name, description, measurement_unit_id, direction) select 'Gestão dos pedidos de abastecimento de Facilities (Contas de Consumo)', 'Realizar controle mensal e semanal dos Materiais de Limpeza e consumo utilizados na Usina (Prédio ADM, Almox e Centro de Vivência) Buscando redução em relação ao orçamento na utilização mensal projetada para 2026.', mu.id, 'menor_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Gestão dos pedidos de abastecimento de Facilities (Contas de Consumo)');
insert into indicators (name, description, measurement_unit_id, direction) select 'Acuracidade do estoque em valor (Inventário Rotativo)', 'Garantir a acuracidade do estoque com base no inventário rotativo considerando o valor total do estoque', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Acuracidade do estoque em valor (Inventário Rotativo)');
insert into indicators (name, description, measurement_unit_id, direction) select 'Classificação e Parametrização de itens (REP, CON, Mín/Máx)', 'Classificar itens como reposição ou consumo, além de definir mínimo, máximo e criticidade conforme base da usina', mu.id, 'percentual_por_mes' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Classificação e Parametrização de itens (REP, CON, Mín/Máx)');
insert into indicators (name, description, measurement_unit_id, direction) select 'Classificação de itens Críticos', 'Classificar itens como reposição ou consumo, além de definir mínimo, máximo e criticidade conforme base da usina', mu.id, 'percentual_por_mes' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Classificação de itens Críticos');
insert into indicators (name, description, measurement_unit_id, direction) select 'Garantir 100% de conformidade nos contratos de limpeza e vigilância através da implementação de um relatório de acompanhamento mensal.', 'Garantir 100% de conformidade nos contratos de limpeza e vigilância através da implementação de um relatório de acompanhamento mensal.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Garantir 100% de conformidade nos contratos de limpeza e vigilância através da implementação de um relatório de acompanhamento mensal.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Conferência e lançamento EUST dentro do prazo.', 'Conferência e lançamento de notas manuais relacionado ao EUST no prazo. Aceitável: 80% 02 dias; 100% 1,5 dias e 120% 01 dia útil.', mu.id, 'menor_melhor' from measurement_units mu where mu.code='DIAS' and not exists (select 1 from indicators i2 where i2.name='Conferência e lançamento EUST dentro do prazo.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Desenvolvimento e implementação de check-list veicular eletrônico', 'Desenvolvimento e implementação de check-list veicular eletronico (Forms), garantindo agilidade e organização em todo o processo.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Desenvolvimento e implementação de check-list veicular eletrônico');
insert into indicators (name, description, measurement_unit_id, direction) select 'Garantir realização de Check List Veículos mensalmente, para toda a frota', 'Garantir o preenchimento dos check lists veiculares, para informar ao setor de segurança do trabalho conforme regimento interno e também para programar e otimizar manutenções preventivas e corretivas necessárias.', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Garantir realização de Check List Veículos mensalmente, para toda a frota');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implantar melhorias no processo de lançamento de Biomassa, com redução do tempo médio de lançamento em 10%', 'Implantar melhorias no processo de lançamento de Biomassa, com redução do tempo médio de lançamento em 10%, sendo nosso tempo padrão atual 7 min.', mu.id, 'menor_melhor' from measurement_units mu where mu.code='MIN' and not exists (select 1 from indicators i2 where i2.name='Implantar melhorias no processo de lançamento de Biomassa, com redução do tempo médio de lançamento em 10%');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implementar controle de consumo de combustível da Frota de Candiota/RS, via BI', 'Implementar controle de consumo de combustível da Frota de Candiota/RS, via BI', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Implementar controle de consumo de combustível da Frota de Candiota/RS, via BI');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implementar controle de uso de veículos da Frota de Candiota/RS, via Corporate', 'Garantir que o controle da utilização dos veículos sob gestão do setor de transportes, seja realizado via Corporate, inclusive apresentando relatório mensal, se possível implementar BI.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Implementar controle de uso de veículos da Frota de Candiota/RS, via Corporate');
insert into indicators (name, description, measurement_unit_id, direction) select 'Implementar o cronograma de treinamentos e reciclagem para os faturistas.', 'Implementar o cronograma de treinamentos e reciclagem para os faturistas ativos das regionais Sul, Sudeste e Centro-Oeste, garantindo 100% de adesão e realização das capacitações até nov/2026 (garantindo a continuidade do negócio e a difusão do conhecimento)', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Implementar o cronograma de treinamentos e reciclagem para os faturistas.');
insert into indicators (name, description, measurement_unit_id, direction) select 'Redução de 5% nos contratos de Portaria e Limpeza/Jardinagem', 'Reduzir em 5% o custo total consolidado dos contratos de portaria (GASP) e limpeza e jardinagem (New Fort) até dez/26, por meio da revisão, readequação e otimização do escopo atual de serviços junto aos fornecedores', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Redução de 5% nos contratos de Portaria e Limpeza/Jardinagem');
insert into indicators (name, description, measurement_unit_id, direction) select 'Reduzir em 20% o custo total de locação de carros das usinas Renováveis da Âmbar', 'Reduzir em 20% o custo consolidado de locação de carros das usinas renováveis até dez/26, tomando como base os custos registrados em junho de 2026, por meio da renegociação de contratos, otimização da frota e controle rigoroso para redução de taxas por excesso de quilometragem', mu.id, 'maior_melhor' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Reduzir em 20% o custo total de locação de carros das usinas Renováveis da Âmbar');
insert into indicators (name, description, measurement_unit_id, direction) select 'Reestruturação física da área Administrativa / Transporte na unidade de Candiota', 'Fazer alterações necessárias no escopo da área administrativa / transporte visando a interação de toda equipe, e maximização dos resultados da equipe.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Reestruturação física da área Administrativa / Transporte na unidade de Candiota');
insert into indicators (name, description, measurement_unit_id, direction) select 'Zerar o saldo de adiantamentos de viagem pendentes no sistema com prazo acima de 60 dias', 'Garantir a conformidade e a liquidação dos adiantamentos de viagem, assegurando que 100% dos acertos sejam realizados dentro do prazo, mantendo zero ocorrências de adiantamentos pendentes no sistema com prazo superior a 60 dias por meio de cobrança ativa e monitoramento contínuo.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Zerar o saldo de adiantamentos de viagem pendentes no sistema com prazo acima de 60 dias');
insert into indicators (name, description, measurement_unit_id, direction) select 'Treinamento e preparação de Backups para as rotinas do EUST', 'Treinamento e preparação de Backups para as rotinas do EUST. Preparar ao menos 2 pessoas assumirem as rotinas do EUST em eventual ausência.', mu.id, 'binario' from measurement_units mu where mu.code='X' and not exists (select 1 from indicators i2 where i2.name='Treinamento e preparação de Backups para as rotinas do EUST');
