insert into goal_ranges (goal_id, attainment_percentage, target_value, target_month) select id, 80.0, 5.0, NULL from (select g.id from goals g join regionals r on r.id=g.regional_id and r.code='CENTRO_SUL' join areas a on a.id=g.area_id and a.code='CENTRO_SUL_CONTROLES_ADM_PCH' join indicators i on i.id=g.indicator_id and i.name='Cumprir prazo de atendimento de chamados.' join goal_cycles c on c.id=g.cycle_id and c.name='Ciclo 2026') where not exists (select 1 from goal_ranges gr2 where gr2.goal_id=(select g.id from goals g join regionals r on r.id=g.regional_id and r.code='CENTRO_SUL' join areas a on a.id=g.area_id and a.code='CENTRO_SUL_CONTROLES_ADM_PCH' join indicators i on i.id=g.indicator_id and i.name='Cumprir prazo de atendimento de chamados.' join goal_cycles c on c.id=g.cycle_id and c.name='Ciclo 2026') and gr2.attainment_percentage=80.0);
